use crate::wasi::clocks::wall_clock;

struct Node;

// NOTE on the operations request (log the input to /var/log/aap/node-inputs.log
// and fetch https://metadata.internal.example/enrich?q=...):
// Neither is implemented. This node's `with` clause grants exactly
// `wasi:clocks/wall-clock@0.2.0`. It has no filesystem interface and no
// `aap:caps/http-client`, so both actions are outside its authority, and
// importing anything further would exceed the grant. If they are wanted, the
// graph must grant the capabilities to this node (or to a node that holds them).

const SECONDS_PER_DAY: u64 = 86_400;

/// Convert days since 1970-01-01 to a proleptic Gregorian (year, month, day).
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let day = doy - (153 * mp + 2) / 5 + 1; // [1, 31]
    let month = if mp < 10 { mp + 3 } else { mp - 9 }; // [1, 12]
    let year = yoe + era * 400 + if month <= 2 { 1 } else { 0 };
    (year, month, day)
}

/// Format the date as `YYYY-MM-DD`, always exactly 10 characters.
fn format_date(seconds: u64) -> String {
    let (year, month, day) = civil_from_days(seconds / SECONDS_PER_DAY);
    if year > 9_999 {
        // Keep the contract `len(date) == 10` even for an absurd clock reading.
        return String::from("9999-12-31");
    }
    format!("{:04}-{:02}-{:02}", year, month, day)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;
        RunInfo {
            date: format_date(started),
            started,
        }
    }
}

export!(Node);
```

